// Input validation for RAG query
const input = $input.first().json;

// Validate required fields
if (!input.query || typeof input.query !== 'string' || input.query.trim().length === 0) {
  return {
    json: {
      success: false,
      error: 'Invalid input: query is required and must be a non-empty string',
      agentType: 'rag_search',
      errorCode: 'INVALID_INPUT'
    }
  };
}

// Sanitize and prepare query for semantic search
const sanitizedQuery = input.query.trim()
  .replace(/<[^>]*>/g, '') // Remove HTML
  .slice(0, 2000); // Limit length

// Determine memory type hints from query
let memoryTypeHint = 'semantic'; // default
if (/past|previous|last time|before|history/i.test(sanitizedQuery)) {
  memoryTypeHint = 'episodic';
} else if (/how to|process|steps|procedure|workflow/i.test(sanitizedQuery)) {
  memoryTypeHint = 'procedural';
}

return {
  json: {
    query: sanitizedQuery,
    sessionId: input.sessionId || $execution.id,
    memoryTypeHint,
    startTime: Date.now(),
    metadata: {
      originalLength: input.query.length,
      memoryTypeHint,
      executionId: $execution.id
    }
  }
};

// Format RAG output with retrieved documents
const input = $('Validate Input').first().json;
const result = $input.first().json;

const executionTime = Date.now() - (input.startTime || Date.now());

// Extract retrieved documents and scores
let retrievedDocuments = [];
let relevanceScores = [];

try {
  if (result.intermediateSteps) {
    for (const step of result.intermediateSteps) {
      if (step.observation) {
        // Parse vector search results
        const obs = typeof step.observation === 'string'
          ? step.observation
          : step.observation;

        // Try to extract document info
        if (typeof obs === 'object' && obs.documents) {
          for (const doc of obs.documents) {
            retrievedDocuments.push({
              id: doc.id || doc.metadata?.id,
              content: doc.pageContent || doc.content,
              metadata: doc.metadata || {},
              score: doc.score
            });
            if (doc.score) {
              relevanceScores.push(doc.score);
            }
          }
        } else if (Array.isArray(obs)) {
          // Array of results
          for (const item of obs) {
            if (item.pageContent || item.content) {
              retrievedDocuments.push({
                id: item.id || item.metadata?.id,
                content: item.pageContent || item.content,
                metadata: item.metadata || {},
                score: item.score
              });
              if (item.score) {
                relevanceScores.push(item.score);
              }
            }
          }
        }
      }
    }
  }
} catch (e) {
  // Non-critical parsing error
}

// Calculate average relevance
const avgRelevance = relevanceScores.length > 0
  ? relevanceScores.reduce((a, b) => a + b, 0) / relevanceScores.length
  : null;

return {
  json: {
    success: true,
    agentType: 'rag_search',
    output: result.output || 'Search completed',
    retrievedDocuments,
    relevanceScores,
    averageRelevance: avgRelevance,
    memoryType: input.memoryTypeHint,
    documentCount: retrievedDocuments.length,
    metadata: {
      executionTime,
      toolCalls: (result.intermediateSteps || []).length,
      queryLength: input.query.length,
      executionId: input.metadata?.executionId
    }
  }
};

// Handle validation error
const input = $input.first().json;

return {
  json: {
    success: false,
    agentType: 'rag_search',
    error: input.error || 'Validation failed',
    errorCode: input.errorCode || 'VALIDATION_ERROR',
    output: null,
    retrievedDocuments: [],
    metadata: {
      executionId: $execution.id
    }
  }
};
